// The model returns a theme in whatever words it chose. Left alone that gives you forty themes
// for the same eight problems, which is the reason "listen to customers" boards get abandoned.
// This lower-cases, trims, folds a few obvious synonyms, and drops anything that is not a
// complaint or is below the severity you set. Edit the synonym map — it is the part that has to
// match your product's vocabulary.
const cfg = $('What to listen for').first().json;
const SYNONYMS = {
  'app speed': 'performance', 'slow app': 'performance', 'lag': 'performance',
  'price': 'pricing', 'cost': 'pricing', 'expensive': 'pricing', 'price increase': 'pricing',
  'support': 'support', 'customer service': 'support', 'help desk': 'support',
  'bugs': 'reliability', 'crashes': 'reliability', 'downtime': 'reliability',
};

const out = [];
for (const item of $input.all()) {
  let parsed;
  try { parsed = JSON.parse(item.json.text); }
  catch (e) { continue; }            // a model that returned prose is skipped, not guessed at

  if (!parsed.is_complaint) continue;
  const severity = Number(parsed.severity) || 0;
  if (severity < Number(cfg.minSeverity || 0)) continue;

  let theme = String(parsed.theme || '').toLowerCase().trim();
  for (const [needle, canonical] of Object.entries(SYNONYMS)) {
    if (theme.includes(needle)) { theme = canonical; break; }
  }

  out.push({
    json: {
      theme,
      severity,
      switching: parsed.switching === true,
      quote: String(parsed.quote || '').trim(),
      source: 'reddit',
      product: cfg.product,
    },
  });
}

return out;

